function loadData() {
  if (typeof window === "undefined") return DEFAULT_DATA;
  try {
    const saved = window.localStorage.getItem(STORAGE_KEY);
    if (!saved) return DEFAULT_DATA;
    const parsed = JSON.parse(saved);
    return {
      ...DEFAULT_DATA,
      ...parsed,
      patients: Array.isArray(parsed.patients) ? parsed.patients : DEFAULT_DATA.patients,
      appointments: Array.isArray(parsed.appointments) ? parsed.appointments : DEFAULT_DATA.appointments,
      meds: Array.isArray(parsed.meds) ? parsed.meds : DEFAULT_DATA.meds,
      settings: { ...DEFAULT_DATA.settings, ...(parsed.settings || {}) },
      beds: { ...DEFAULT_DATA.beds, ...(parsed.beds || {}) },
    };
  } catch {
    return DEFAULT_DATA;
  }
}

