const COLOR_MAP = {
  teal: "bg-teal-50 text-teal-700 ring-teal-100",
  blue: "bg-blue-50 text-blue-700 ring-blue-100",
  violet: "bg-violet-50 text-violet-700 ring-violet-100",
  amber: "bg-amber-50 text-amber-700 ring-amber-100",
  rose: "bg-rose-50 text-rose-700 ring-rose-100",
};
function getMedStatus(med) {
  const days = Math.ceil((new Date(`${med.expiry}T00:00:00`) - new Date(`${todayISO()}T00:00:00`)) / 86400000);
  if (days < 0) return { key: "expired", label: "منتهي الصلاحية", className: "bg-rose-50 text-rose-700 ring-rose-200", dot: "bg-rose-500", detail: `منتهي منذ ${Math.abs(days)} يوم` };
  if (days <= 60) return { key: "soon", label: "قرب انتهاء الصلاحية", className: "bg-orange-50 text-orange-700 ring-orange-200", dot: "bg-orange-500", detail: `متبقي ${days} يوم` };
  if (med.qty < med.min) return { key: "low", label: "مخزون منخفض", className: "bg-amber-50 text-amber-700 ring-amber-200", dot: "bg-amber-500", detail: `${med.qty} وحدة متبقية` };
  return { key: "ok", label: "متوفر", className: "bg-emerald-50 text-emerald-700 ring-emerald-200", dot: "bg-emerald-500", detail: "المخزون ضمن الحد" };
}

