function Badge({ status, children, className = "" }) {
  const info = status || { label: children, className: "bg-slate-100 text-slate-600 ring-slate-200", dot: "bg-slate-400" };
  return <span className={`inline-flex items-center gap-1.5 whitespace-nowrap rounded-full px-2.5 py-1 text-[11px] font-semibold ring-1 ring-inset ${info.className} ${className}`}><span className={`h-1.5 w-1.5 rounded-full ${info.dot}`} />{children || info.label}</span>;
}
function Avatar({ name, initials, color = "teal", size = "md" }) {
  const dimension = size === "sm" ? "h-9 w-9 text-[11px]" : size === "lg" ? "h-12 w-12 text-sm" : "h-10 w-10 text-xs";
  return <span className={`inline-flex ${dimension} shrink-0 items-center justify-center rounded-2xl font-bold ring-1 ${COLOR_MAP[color] || COLOR_MAP.teal}`} aria-label={name}>{initials || name?.slice(0, 2) || "؟"}</span>;
}
function SectionTitle({ title, subtitle, action, className = "" }) {
  return <div className={`mb-5 flex flex-wrap items-end justify-between gap-3 ${className}`}><div><h2 className="text-[15px] font-extrabold tracking-tight text-slate-900">{title}</h2>{subtitle && <p className="mt-1 text-xs leading-5 text-slate-500">{subtitle}</p>}</div>{action}</div>;
}
